function updateMain(html) {
  html = html.replace(/<article class="section-card nutrient-card"><h2>([^<]+)<\/h2><p>More detailed nutrient information, food sources, and practical guidance will be added here\.<\/p><\/article>/g, (match, encodedName) => {
    const name = encodedName.replace(/&amp;/g, "&");
    const file = linkMap.get(name);
    if (!file) return match;
    return `<a class="section-card card-link nutrient-card" href="${file}"><h2>${encodedName}</h2><p>Explore functions, food sources, possible deficiency signs, risk factors, safety, and frequently asked questions.</p><span class="button-link">Learn About ${encodedName}</span></a>`;
  });
  const deficiencyLinks = new Map([["Calcium Deficiency","calcium.html"],["Folate Deficiency","vitamin-b9-folate.html"],["Iron Deficiency","iron.html"],["Magnesium Deficiency","magnesium.html"],["Vitamin B12 Deficiency","vitamin-b12.html"],["Vitamin D Deficiency","vitamin-d.html"],["Zinc Deficiency","zinc.html"]]);
  html = html.replace(/<article class="section-card nutrient-card"><h2>([^<]+ Deficiency)<\/h2><p>More detailed nutrient information, food sources, and practical guidance will be added here\.<\/p><\/article>/g, (match, title) => {
    const file = deficiencyLinks.get(title);
    return file ? `<a class="section-card card-link nutrient-card" href="${file}#possible-deficiency"><h2>${title}</h2><p>Review possible signs, risk factors, testing considerations, and reasons to seek professional guidance.</p><span class="button-link">Learn More</span></a>` : match;
  });
  const marker = `      <section class="resource-section" aria-labelledby="final-takeaways">`;
  if (!html.includes("common-symptoms-nutrients")) {
    const additions = `      <section class="resource-section" aria-labelledby="common-symptoms-nutrients">
        <h2 id="common-symptoms-nutrients">Common Symptoms &amp; Nutrients To Consider</h2>
        <p>Symptoms are not diagnoses and often have many possible causes. These future guides will help visitors prepare informed questions for a healthcare professional.</p>
        <div class="sections-grid">${symptomCards.map(([title, file, text]) => `<a class="section-card card-link nutrient-card" href="${file}"><h3>${esc(title)}</h3><p>${esc(text)}</p><span class="button-link">Open Future Guide</span></a>`).join("")}</div>
      </section>

      <section class="resource-section" aria-labelledby="nutrient-relationships">
        <h2 id="nutrient-relationships">Nutrient Relationships</h2>
        <p>Nutrients work together. These future guides will explain helpful relationships, balance, absorption, and reasons not to treat one nutrient in isolation.</p>
        <div class="sections-grid">${relationships.map(([title, file]) => `<a class="section-card card-link nutrient-card" href="${file}"><h3>${esc(title)}</h3><p>Explore how these nutrients interact and why food patterns, medicines, health conditions, and total intake matter.</p><span class="button-link">Open Future Guide</span></a>`).join("")}</div>
      </section>

`;
    html = html.replace(marker, additions + marker);
  } else {
    html = html.replace(/<div class="sections-grid"><article class="section-card nutrient-card"><h3>Fatigue<\/h3>[\s\S]*?<\/div>\s*<\/section>\s*\n\s*<section class="resource-section" aria-labelledby="nutrient-relationships">/, `<div class="sections-grid">${symptomCards.map(([title, file, text]) => `<a class="section-card card-link nutrient-card" href="${file}"><h3>${esc(title)}</h3><p>${esc(text)}</p><span class="button-link">Open Future Guide</span></a>`).join("")}</div>\n      </section>\n\n      <section class="resource-section" aria-labelledby="nutrient-relationships">`);
    html = html.replace(/<div class="sections-grid"><article class="section-card nutrient-card"><h3>Vitamin D \+ Calcium<\/h3>[\s\S]*?<\/div>\s*<\/section>\s*\n\s*<section class="resource-section" aria-labelledby="final-takeaways">/, `<div class="sections-grid">${relationships.map(([title, file]) => `<a class="section-card card-link nutrient-card" href="${file}"><h3>${esc(title)}</h3><p>Explore how these nutrients interact and why food patterns, medicines, health conditions, and total intake matter.</p><span class="button-link">Open Future Guide</span></a>`).join("")}</div>\n      </section>\n\n      <section class="resource-section" aria-labelledby="final-takeaways">`);
  }
  return html;
}

